    border-radius: 25px;
    margin-top: 25px;
    border: rgb(236, 236, 236) 1px solid;
}

.post-container h2,
.post-container p {
    text-align: left;
    width: 100%;
}

h2, a{
    color: #5c99fa;
}

h1{
    color: #005ea6;
}

.post-container > p{
    margin-top: -1rem;
}

.button-container{
    display: flex;
    flex-direction: row;
    align-self: flex-start;
    gap: 30px;
}

.button-container > form > input{
    width: 100px;
    background-color: #5c99fa;
    border-radius: 25px;
    border: 1px #005ea6 solid;
}

button{
    background-color: #5c99fa;
    border: 1px #005ea6 solid;
}

.new-post-container{
    width: 80%;
    display: flex;
    flex-direction: column;
    margin: auto;
    align-items: center;
    gap: 2rem;
}

.new-post-container > input, textarea{
    width: 50%;
    background-color: rgb(240, 240, 240);
    border: 1px #005ea6 solid; 
    resize: none;
